package com.school.identity.api;
import com.school.identity.domain.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/identity") public class IdentityController {private final UserAccountRepository users;private final RoleRepository roles;private final PermissionRepository permissions;public IdentityController(UserAccountRepository users,RoleRepository roles,PermissionRepository permissions){this.users=users;this.roles=roles;this.permissions=permissions;}@GetMapping("/roles")List<RoleResponse>listRoles(){return roles.findAllByOrderByNameAsc().stream().map(r->new RoleResponse(r.getCode(),r.getName())).toList();}@GetMapping("/permissions")List<PermissionResponse>listPermissions(){return permissions.findAllByOrderByCodeAsc().stream().map(p->new PermissionResponse(p.getCode(),p.getName(),p.getDescription())).toList();}@GetMapping("/users")List<UserResponse>listUsers(@RequestHeader("X-School-Id")UUID schoolId){return users.findAllBySchoolIdOrderByDisplayNameAsc(schoolId).stream().map(UserResponse::from).toList();}@PostMapping("/users")@ResponseStatus(HttpStatus.CREATED)UserResponse create(@RequestHeader("X-School-Id")UUID schoolId,@Valid @RequestBody CreateUserRequest request){if(users.existsBySchoolIdAndUsername(schoolId,request.username())||users.existsBySchoolIdAndEmail(schoolId,request.email()))throw new ConflictException("Username or email already exists for this school.");return UserResponse.from(users.save(new UserAccount(schoolId,request.username(),request.email(),request.displayName(),request.keycloakSubject(),resolveRoles(request.roles()))));}@PutMapping("/users/{id}/roles")UserResponse setRoles(@RequestHeader("X-School-Id")UUID schoolId,@PathVariable("id")UUID id,@Valid @RequestBody RoleAssignmentRequest request){UserAccount user=findUser(id,schoolId);user.changeRoles(resolveRoles(request.roles()));return UserResponse.from(users.save(user));}@PutMapping("/users/{id}/status")UserResponse setStatus(@RequestHeader("X-School-Id")UUID schoolId,@PathVariable("id")UUID id,@Valid @RequestBody StatusRequest request){UserAccount user=findUser(id,schoolId);user.changeStatus(request.status());return UserResponse.from(users.save(user));}private UserAccount findUser(UUID id,UUID schoolId){return users.findByIdAndSchoolId(id,schoolId).orElseThrow(()->new NotFoundException("User not found."));}private Set<Role>resolveRoles(Set<String>requested){List<Role>found=roles.findAllByCodeIn(requested);if(found.size()!=requested.size())throw new NotFoundException("One or more roles do not exist.");return new LinkedHashSet<>(found);}record CreateUserRequest(@NotBlank @Pattern(regexp="^[a-zA-Z0-9._-]{3,100}$")String username,@Email @NotBlank String email,@NotBlank @Size(max=200)String displayName,@Size(max=100)String keycloakSubject,@NotEmpty Set<String>roles){}record RoleAssignmentRequest(@NotEmpty Set<String>roles){}record StatusRequest(@Pattern(regexp="ACTIVE|SUSPENDED")String status){}record RoleResponse(String code,String name){}record PermissionResponse(String code,String name,String description){}record UserResponse(UUID id,String username,String email,String displayName,String keycloakSubject,String status,Set<String>roles){static UserResponse from(UserAccount u){return new UserResponse(u.getId(),u.getUsername(),u.getEmail(),u.getDisplayName(),u.getKeycloakSubject(),u.getStatus(),u.getRoles().stream().map(Role::getCode).collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new)));}}static class NotFoundException extends RuntimeException{NotFoundException(String m){super(m);}}static class ConflictException extends RuntimeException{ConflictException(String m){super(m);}}}
